CREATE TABLE IF NOT EXISTS gis_phase352_metadata_reconstruction (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_id TEXT, target_id TEXT, source_feature_key TEXT, target_feature_key TEXT, source_parent_id TEXT, target_parent_id TEXT, source_state_code TEXT, target_state_code TEXT, source_provider TEXT, target_provider TEXT, source_srid INTEGER, target_srid INTEGER, source_normalized_srid INTEGER, target_normalized_srid INTEGER, source_valid BOOLEAN, target_valid BOOLEAN, source_empty BOOLEAN, target_empty BOOLEAN, parent_relationship TEXT, metadata_status TEXT NOT NULL, issues JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));